#!/bin/sh
# haiggoh-shim v1 plugin=@PLUGIN@ target=@REL@
# GENERATED by install/wire-statusline.sh — do not edit by hand; the next install run
# rewrites this file. It exists so that every entry point resolves its plugin
# directory at EVERY invocation: a plugin update then takes effect with no re-wiring,
# and a branch switch in a workspace checkout changes nothing live.
#
# WHY A SHIM AND NOT A SYMLINK: a symlink is frozen at install time, so it names a
# version directory that the next update leaves behind, and the entry point silently
# keeps running the old copy. A shim is eight lines of resolution plus an exec.
#
# Resolution order (identical to bin/cost-tracker-resolve.sh, inlined because a shim
# cannot call a resolver it has not found yet):
#   (a) $@OVERRIDE@ — the explicit override. Set but invalid is a HARD ERROR: a typo
#       must fail loudly rather than silently resolve somewhere else.
#   (b) the cached answer in $HOME/.cache/haiggoh-shims/@PLUGIN@, reused only while
#       the registry's mtime is unchanged and the recorded dir still holds a manifest.
#   (c) the installPath recorded in installed_plugins.json for @PLUGIN@haiggoh — the
#       user's chosen first, so statusLine and hooks always run the same version.
#   (d) the highest semver dir under the plugin cache.
#   (e) nothing found: exit 1 with one line on stderr.
#
# Usage:  <shim> [args...]     exec the target with args
#         <shim> --which       print the resolved TARGET path and exit 0
#
# ARGUMENTS ARE FORWARDED, NOT PARSED — including --help and unknown flags. That is
# deliberate and is the shim's whole contract: intercepting --help would break any
# target that takes its own --help, and rejecting an unknown flag would break a target
# that has flags this template has never heard of. A user probing this file with
# --help therefore gets the TARGET's usage (the thing they wanted), and a bad flag
# exits 2 from the target that owns it. The single exception is the first-argument
# query described in the Usage line above.
set -u

PLUGIN_NAME='@PLUGIN@'
OVERRIDE_VAR='@OVERRIDE@'
REL_TARGET='@REL@'
PLUGINS_DIR="${CLAUDE_PLUGINS_DIR:-$HOME/.claude/plugins}"
REGISTRY="$PLUGINS_DIR/installed_plugins.json"
REG_KEY="$PLUGIN_NAME@haiggoh"
CACHE_ROOT="${HAIGGOH_SHIM_CACHE:-$HOME/.cache/haiggoh-shims}"
CACHE_FILE="$CACHE_ROOT/$PLUGIN_NAME"

die() { printf '%s: %s\n' "$PLUGIN_NAME" "$1" >&2; exit 1; }

# --- helpers ---------------------------------------------------------------------
# A file's content checksum. Deliberately NOT the mtime: a registry rewritten twice
# inside the same second has an identical mtime on macOS (1-second granularity), so a
# mtime-keyed cache would keep serving the first answer -- measured as a real failure.
# A checksum sees any change, and costs one tiny fork instead of a python one.
_reg_key() { [ -f "$1" ] && cksum < "$1" 2>/dev/null | cut -d" " -f1; }

# highest version among "$1"/*, dirs that hold .claude-plugin/plugin.json only
_best_cache_dir() {
    _best=""
    for _d in "$1"/*/; do
        [ -f "$_d/.claude-plugin/plugin.json" ] || continue
        if [ -z "$_best" ]; then _best="$_d"; continue; fi
        _a=$(printf '%s\n' "${_d##*/}" | awk -F. '{printf "%05d%05d%05d%05d", $1+0, $2+0, $3+0, $4+0}')
        _b=$(printf '%s\n' "${_best##*/}" | awk -F. '{printf "%05d%05d%05d%05d", $1+0, $2+0, $3+0, $4+0}')
        [ "$_a" -ge "$_b" ] && _best="$_d"
    done
    [ -n "$_best" ] && printf '%s\n' "${_best%/}"
}

_registry_installpath() {
    [ -f "$REGISTRY" ] || return 1
    _REG="$REGISTRY" _KEY="$REG_KEY" python3 -c '
import json, os, sys
try:
    with open(os.environ["_REG"]) as f:
        data = json.load(f)
except Exception:
    sys.exit(1)                      # unreadable or malformed: not an error here
plugins = data.get("plugins") if isinstance(data, dict) else None
entries = plugins.get(os.environ["_KEY"]) if isinstance(plugins, dict) else None
if not isinstance(entries, list):
    sys.exit(1)
for entry in entries:
    if not isinstance(entry, dict):
        continue
    path = entry.get("installPath")
    if not isinstance(path, str) or not path:
        continue
    if os.path.isfile(os.path.join(path, ".claude-plugin", "plugin.json")):
        print(path)                 # the first USABLE entry wins
        sys.exit(0)
sys.exit(1)
' 2>/dev/null
}

_resolve() {
    # (a) the override, read indirectly so one template serves every plugin
    _ov=$(eval "printf '%s' \"\${$OVERRIDE_VAR:-}\"")
    if [ -n "$_ov" ]; then
        [ -f "$_ov/.claude-plugin/plugin.json" ] \
            || die "$OVERRIDE_VAR=$_ov is not a plugin dir (no .claude-plugin/plugin.json)"
        printf '%s\n' "${_ov%/}"
        return 0
    fi

    # (b) the cached answer, valid only while the registry has not moved
    _reg_mtime=$(_reg_key "$REGISTRY")
    if [ -n "$_reg_mtime" ] && [ -f "$CACHE_FILE" ]; then
        _cached_mtime=$(awk 'NR==1{print $1}' "$CACHE_FILE" 2>/dev/null)
        _cached_dir=$(awk 'NR==1{print $2}' "$CACHE_FILE" 2>/dev/null)
        if [ "$_cached_mtime" = "$_reg_mtime" ] && [ -n "$_cached_dir" ] \
           && [ -f "$_cached_dir/.claude-plugin/plugin.json" ]; then
            printf '%s\n' "${_cached_dir%/}"
            return 0
        fi
    fi

    # (c) the registry, then (d) the cache
    _dir=$(_registry_installpath)
    if [ -z "$_dir" ]; then
        _dir=$(_best_cache_dir "$PLUGINS_DIR/cache/haiggoh/$PLUGIN_NAME")
    fi
    if [ -z "$_dir" ]; then
        die "no installed $PLUGIN_NAME found (tried \$$OVERRIDE_VAR, $REGISTRY, and $PLUGINS_DIR/cache/haiggoh/$PLUGIN_NAME)"
    fi

    # (b) refresh the cache for the next warm call — best effort, never fatal
    if [ -n "$_reg_mtime" ]; then
        mkdir -p "$CACHE_ROOT" 2>/dev/null && printf '%s %s\n' "$_reg_mtime" "$_dir" > "$CACHE_FILE" 2>/dev/null
    fi
    printf '%s\n' "$_dir"
}

# --- the one thing this shim is for ----------------------------------------------
# NOT `_dir=$(_resolve)`: a `die` inside a command substitution exits only the
# subshell, so the script would carry on with an empty dir and print a second,
# meaningless error. Taking the status here gives exactly one message and one exit.
if ! _dir=$(_resolve); then
    exit 1                              # _resolve already said why on stderr
fi
_target="$_dir/$REL_TARGET"

# --which is honoured only as the first argument, so a target that takes a literal
# such argument still works.
if [ "${1:-}" = "--which" ]; then
    [ -f "$_target" ] || die "resolved $_dir but $REL_TARGET is not there"
    printf '%s\n' "$_target"
    exit 0
fi

[ -f "$_target" ] || die "resolved $_dir but $REL_TARGET is not there"
exec "$_target" "$@"
